import { chromium, devices } from 'playwright';
import fs from 'node:fs';

/**
 * Captures the README screenshots from the real production build.
 * Nothing here is mocked: the DNA shown is generated by the shipped engine.
 */
const BASE = 'http://127.0.0.1:4186/digital-dna/';
const OUT = 'docs/screenshots';
fs.mkdirSync(OUT, { recursive: true });

const browser = await chromium.launch();

async function buildOne(page, nick) {
  await page.goto(`${BASE}#/create`);
  await page.getByRole('heading', { name: /Identity/i }).first().waitFor();
  await page.getByLabel(/Nickname/i).fill(nick);
  await page.getByLabel(/Short bio/i).fill('Designs interfaces by day, collects synthesizers by night. Currently rebuilding a personal knowledge system.');
  await page.getByLabel(/^Role/i).fill('Product designer');
  await page.getByLabel(/^Field/i).fill('Design systems');
  await page.getByRole('button', { name: /Continue/i }).click();

  await page.getByText(/Pick your domains/i).first().waitFor();
  for (const name of ['Design', 'AI', 'Art', 'Music', 'Technology', 'Photography']) {
    await page.getByRole('button', { name, exact: true }).click();
  }
  // Bump a couple of intensities so the artwork reads as uneven.
  const sliders = page.getByRole('group', { name: 'Interest intensity' });
  await sliders.nth(0).getByRole('button', { name: /^5 / }).click();
  await sliders.nth(1).getByRole('button', { name: /^4 / }).click();
  await page.getByRole('button', { name: /Continue/i }).click();

  await page.getByText(/What can you do/i).first().waitFor();
  for (const name of ['Design', 'Video Editing', 'Communication', 'Programming']) {
    await page.getByRole('button', { name, exact: true }).click();
  }
  await page.getByRole('button', { name: /Continue/i }).click();

  await page.getByText(/What do you most like to make/i).first().waitFor();
  await page.getByRole('button', { name: /Visuals/i }).first().click();
  await page.getByRole('button', { name: /Stories/i }).first().click();
  await page.getByRole('button', { name: /With a team/i }).click();
  await page.getByRole('button', { name: /Go deeper into what I know/i }).click();
  await page.getByRole('button', { name: /^Visually/i }).click();
  await page.getByRole('button', { name: /Long-term polishing/i }).click();
  await page.getByRole('button', { name: /Continue/i }).click();

  await page.getByText(/Platforms you spend time on/i).first().waitFor();
  for (const name of ['X / Twitter', 'YouTube', 'Instagram']) {
    await page.getByRole('button', { name, exact: true }).click();
  }
  for (const name of ['Figma', 'Photoshop', 'Spotify', 'Notion']) {
    await page.getByRole('button', { name, exact: true }).first().click();
  }
  for (const name of ['Long-form articles', 'Design portfolios', 'Documentaries']) {
    await page.getByRole('button', { name, exact: true }).click();
  }
  await page.getByRole('button', { name: /Continue/i }).click();

  await page.getByText(/Pick the aesthetic/i).first().waitFor();
  await page.getByRole('button', { name: /Abstract/i }).first().click();
  await page.getByRole('button', { name: /Continue/i }).click();

  await page.getByText(/Ready/i).first().waitFor();
  await page.getByRole('button', { name: /Generate my DNA/i }).click();
  await page.getByText(/^DNA-[0-9A-F]{6}$/).first().waitFor({ timeout: 25000 });
  await page.waitForTimeout(2500);
}

// ---------------------------------------------------------------- desktop
const desktop = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 2 });
const page = await desktop.newPage();

await page.goto(BASE);
await page.waitForTimeout(1600);
await page.screenshot({ path: `${OUT}/01-home.png` });

await buildOne(page, 'Iris Vale');
await page.screenshot({ path: `${OUT}/02-dna-result.png`, fullPage: false });
await page.evaluate(() => window.scrollTo(0, 700));
await page.waitForTimeout(500);
await page.screenshot({ path: `${OUT}/03-dna-analysis.png` });
await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight));
await page.waitForTimeout(400);
await page.screenshot({ path: `${OUT}/04-dna-share.png` });

// Wizard screenshot at step 2.
await page.goto(`${BASE}#/create`);
await page.getByRole('heading', { name: /Identity/i }).first().waitFor();
await page.waitForTimeout(700);
await page.screenshot({ path: `${OUT}/05-wizard.png` });

// Compare.
await page.goto(`${BASE}#/compare`);
await page.getByText(/Two helixes, side by side/i).waitFor();
await page.waitForTimeout(1200);
await page.screenshot({ path: `${OUT}/06-compare.png` });

// Evolution (needs a second version): add an interest and regenerate.
await page.goto(`${BASE}#/create`);
await page.getByRole('heading', { name: /Identity/i }).first().waitFor();
await page.getByRole('button', { name: /Continue/i }).click();
await page.getByRole('button', { name: 'Crypto', exact: true }).click();
await page.getByRole('button', { name: 'Entrepreneurship', exact: true }).click();
// Advance step by step until the review screen appears.
for (let i = 0; i < 6; i++) {
  const gen = page.getByRole('button', { name: /Generate my DNA/i });
  if (await gen.isVisible().catch(() => false)) break;
  await page.getByRole('button', { name: /Continue/i }).click();
  await page.waitForTimeout(250);
}
await page.getByRole('button', { name: /Generate my DNA/i }).click();
await page.getByText(/^DNA-[0-9A-F]{6}$/).first().waitFor({ timeout: 25000 });
await page.goto(`${BASE}#/evolution`);
await page.getByText(/How your identity changed/i).waitFor();
await page.waitForTimeout(900);
await page.screenshot({ path: `${OUT}/07-evolution.png` });

// Settings.
await page.goto(`${BASE}#/settings`);
await page.waitForTimeout(900);
await page.screenshot({ path: `${OUT}/08-settings.png` });

await desktop.close();

// ------------------------------------------------------------------ mobile
const mobileCtx = await browser.newContext({ ...devices['iPhone 13'], deviceScaleFactor: 3 });
const m = await mobileCtx.newPage();
await m.goto(BASE);
await m.waitForTimeout(1600);
await m.screenshot({ path: `${OUT}/09-mobile-home.png` });

await buildOne(m, 'Iris Vale');
await m.screenshot({ path: `${OUT}/10-mobile-result.png` });
await m.evaluate(() => window.scrollTo(0, 900));
await m.waitForTimeout(500);
await m.screenshot({ path: `${OUT}/11-mobile-analysis.png` });

await mobileCtx.close();
await browser.close();

console.log('screenshots written:');
for (const f of fs.readdirSync(OUT)) {
  console.log(' ', f, fs.statSync(`${OUT}/${f}`).size, 'bytes');
}
